contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        c.SetMinSum(_val); if (__ESBMC_reverted()) return;

        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        assert(afterMinSum == _val && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

