contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _val) internal {
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        try c.SetMinSum(_val) {} catch { return; }
        uint256 afterMinSum;
        try c.MinSum() returns (uint256 __r) { afterMinSum = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterMinSum == _val && afterBalance == beforeBalance);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
